mapper.select:
SELECT aa.*, am_chat.model_name AS modelName, am_chat.provider AS modelProvider, ci_chat.instance_name AS chatInstanceName, ci_embed.instance_name AS embeddingInstanceName, ci_image.instance_name AS imageInstanceName, ap.prompt_title AS promptTitle, ( SELECT se.avatar FROM SYSTEM_EXTENSION se WHERE se.env_code = aa.env_code AND (se.deleted = 0 OR se.deleted IS NULL) AND am_chat.provider IS NOT NULL AND am_chat.provider != '' AND (se.provider_code = am_chat.provider OR se.extension_key = am_chat.provider) ORDER BY CASE WHEN se.provider_code = am_chat.provider THEN 0 ELSE 1 END LIMIT 1 ) AS providerAvatar FROM AI_AGENT aa LEFT JOIN AI_INSTANCE ci_chat ON ci_chat.instance_key = aa.chat_instance_key AND ci_chat.env_code = aa.env_code AND (ci_chat.deleted = 0 OR ci_chat.deleted IS NULL) LEFT JOIN AI_MODEL am_chat ON am_chat.model_key = ci_chat.model_key AND am_chat.env_code = aa.env_code AND (am_chat.deleted = 0 OR am_chat.deleted IS NULL) LEFT JOIN AI_INSTANCE ci_embed ON ci_embed.instance_key = aa.embedding_instance_key AND ci_embed.env_code = aa.env_code AND (ci_embed.deleted = 0 OR ci_embed.deleted IS NULL) LEFT JOIN AI_INSTANCE ci_image ON ci_image.instance_key = aa.image_instance_key AND ci_image.env_code = aa.env_code AND (ci_image.deleted = 0 OR ci_image.deleted IS NULL) LEFT JOIN ( SELECT env_code, prompt_key, MAX(version) AS max_version FROM AI_PROMPT WHERE deleted = 0 GROUP BY env_code, prompt_key ) latest_p ON latest_p.env_code = aa.env_code AND latest_p.prompt_key = aa.prompt_key LEFT JOIN AI_PROMPT ap ON ap.prompt_key = aa.prompt_key AND ap.env_code = aa.env_code AND ap.version = latest_p.max_version AND (ap.deleted = 0 OR ap.deleted IS NULL) WHERE (aa.deleted = 0 OR aa.deleted IS NULL)
AND aa.env_code = #{req.envCode}
AND aa.agent_name LIKE CONCAT('%', #{req.name}, '%')
AND aa.status = #{req.status}
ORDER BY aa.create_time DESC
